def fitness_get_total_number_of_sequences(m, n):
    # T[i][j] = number of sequences of length j ending with value i
    T = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(m + 1):
        T[i][1] = 1  # Base case: sequences of length 1 ending at i

    for j in range(2, n + 1):
