def fitness_numOfSubarrays(arr, k, threshold):
    if len(arr) < k:
        return 0
    bar = k * threshold
    fitness_total = 0
    window = sum(arr[:k])
    if window >= bar:
        fitness_total += 1
    for i in range(k, len(arr)):
        window -= arr[i - k]
        window += arr[i]
        if window >= bar:
            fitness_total += 1
    return fitness_total

