def monitor_bitwiseComplement(N):
    if N == 0:
        return 0
    dummy_num = N
    n = 0
    while dummy_num:
        n -= 1
        dummy_num >>= 1
    monitor_ans = 1
    for i in range(n, -1, -1):
        if (N >> i) & 1 == 0:
            monitor_ans |= 1 << i
    return monitor_ans

